import React, { useState, useEffect } from 'react';
import './Intro.css';

function Intro({ onComplete }) {
  const [displayText, setDisplayText] = useState('TL');

  useEffect(() => {
    // Check if user has already seen the animation this session
    const hasSeenAnimation = sessionStorage.getItem('hasSeenIntro');
    
    if (hasSeenAnimation) {
      // Skip animation - go straight to content
      onComplete();
    } else {
      // Show TL initially
      setDisplayText('TL');
      
      // Expand to full name
      const expandTimeout = setTimeout(() => {
        setDisplayText('Tina Liu');
      }, 5000);
      
      // Show main content after animation
      const completeTimeout = setTimeout(() => {
        sessionStorage.setItem('hasSeenIntro', 'true');
        onComplete();
      }, 10000);
      
      return () => {
        clearTimeout(expandTimeout);
        clearTimeout(completeTimeout);
      };
    }
  }, [onComplete]);

  return (
    <div className="intro-container">
      <div className="logo-wrapper">
        <div className="logo-text" id="logoText">{displayText}</div>
      </div>
    </div>
  );
}

export default Intro;
